Method.Implementation:
	#dim jmsgateway As EnsLib.JavaGateway.JavaGateway
	set jmsgateway = ""
	set topicConnection = ""
	set topicSubscriber = ""

	Set tStat = $$$OK

	$$$LOGINFO("JMSinboundAdapter OnTask")
	// get an instance of JMSGateway and connect to JMSGateway Super Server
	try {
		Set jmsgateway=##class(EnsLib.JavaGateway.JavaGateway).%New()
		Set classPath=##class(%ListOfDataTypes).%New()
		$$$LOGINFO("To connect")

		Do classPath.Insert(..JMSJarPath)
		$$$LOGINFO("JMS Call Path added: " _ ..JMSJarPath)
		Set tStat=jmsgateway.%Connect(..JavaGateWayHost,..JavaGateWayPort,$NAMESPACE,5,classPath) 
		If 'tStat 
		{
			set tStat = $$$ISERR(status)
			set exp = ##class(%Exception.General).%New()
			set exp.Code = status.Name
			set exp.Data = status.Data
			set exp.Name = "Java Gateway connection error"
			Throw exp  
		}
		$$$LOGINFO("Connected to Java Gateway")
		Set tcf=$classmethod(..JmsContainerClass,"%New",jmsgateway, ..JMSHost, ..JMSPort)
		// set tcf = ##class(com.seebeyond.jms.client.STCTopicConnectionFactory).%New(jmsgateway, ..JMSHost, ..JMSPort)
	    set topicConnection = tcf.createTopicConnection()
	    do topicConnection.stop()
	    $$$LOGINFO("Connected to JMS Queue: " _ tcf)
	    $$$LOGINFO("Connected to JMS: " _ ..JMSHost _ ":" _ ..JMSPort)

	    set topicSession = topicConnection.createTopicSession(1, 1) // "true","Session.AUTO_ACKNOWLEDGE")

        set topic = topicSession.createTopic(..TopicName)
        $$$LOGINFO("Created sub: " _ ..TopicName)

        set topicSubscriber = topicSession.createDurableSubscriber(topic, "EnsembleTestDemo")
        $$$LOGINFO("createSubscriber")
        do topicConnection.start()
        do {
        	$$$LOGINFO("receive with timeout")
    		set message=topicSubscriber.receive(5000)
    		$$$LOGINFO("receive: " _ message)
    		if message = ""
    		{
	    		Set tStat=$$$ERROR($$$EnsErrGeneral,"No message in the queue")
    		}
   			elseif message.%IsA("javax.jms.TextMessage")
			{
	   			$$$LOGINFO("Got a TextMessage: " _ message.getText())
	   			Set tStat = ..SendMessageToService(message.getText())	   
			}
			elseif message.%IsA("javax.jms.BytesMessage")
			{
				set arrLen = 500
				set comMsg = ""
				$$$LOGINFO("Got a BytesMessage")
				Set readStream=##class(%GlobalBinaryStream).%New()
        		// reserve a number of bytes since we are passing the stream by reference      
        		For i=1:1:arrLen Do readStream.Write("0")

        		do {            
		    		set bytesRead = message.readBytes(.readStream, arrLen)
		    		set msgText = readStream.Read(bytesRead)
		    		set comMsg = comMsg _ msgText
		  		 	// $$$LOGINFO( "byte msg. length " _ bytesRead )
        		} while (bytesRead = arrLen)
		  		$$$LOGINFO("Create stream")
		  		Set tStat = ..SendMessageToService(comMsg)		
			}
			$$$LOGINFO("Commit and close")
			Do topicSession.commit()
        } while message '= ""
		Do topicSubscriber.close()


	    Do topicConnection.stop()
	    Do topicConnection.close()
	    $$$LOGINFO("Disconnect")
		Do jmsgateway.%Disconnect() 
	 } catch err
     {
	    if (topicConnection '= "")
	    {
	      Do topicConnection.stop()
	      Do topicConnection.close()
	    }

	    if (topicSubscriber '= "")
	    {
	       Do topicSubscriber.close()
	    }

	    if (jmsgateway '= "")
	    {
		  	    Do jmsgateway.%Disconnect()
	    }
    }

	Quit tStat
